// SamlEntityDescriptorToYAML converts SamlEntityDescriptor to YAML bytes.
// Converts to JSON first, then to YAML for proper protobuf handling.
func SamlEntityDescriptorToYAML(v *SamlEntityDescriptor) ([]byte, error) {
	if v == nil {
		return nil, protoerrors.NewErrMissingInvalidData(nil, "samlentitydescriptor is nil")
	}
	// Convert to JSON first
	jsonData, err := SamlEntityDescriptorToJSON(v)
	if err != nil {
		return nil, err
	}
	// Convert JSON to YAML, preserving integer precision
	dec := json.NewDecoder(bytes.NewReader(jsonData))
	dec.UseNumber()
	var obj any
	if err := dec.Decode(&obj); err != nil {
		return nil, err
	}
	return yaml.Marshal(convertJSONNumbers(obj))
}

// SamlEntityDescriptorToTOML converts SamlEntityDescriptor to TOML bytes.
// Converts to JSON first, then to TOML for proper protobuf handling.
func SamlEntityDescriptorToTOML(v *SamlEntityDescriptor) ([]byte, error) {
	if v == nil {
		return nil, protoerrors.NewErrMissingInvalidData(nil, "samlentitydescriptor is nil")
	}
	// Convert to JSON first
	jsonData, err := SamlEntityDescriptorToJSON(v)
	if err != nil {
		return nil, err
	}
	// Convert JSON to TOML
	var obj any
	if err := json.Unmarshal(jsonData, &obj); err != nil {
		return nil, err
	}
	return toml.Marshal(obj)
}

// convertJSONNumbers recursively walks a value decoded with json.UseNumber()
// and converts json.Number back to int64 or float64 so YAML marshals them
// as plain numbers instead of quoted strings.
func convertJSONNumbers(v any) any {
	switch val := v.(type) {
	case json.Number:
		if i, err := val.Int64(); err == nil {
			return i
		}
		if f, err := val.Float64(); err == nil {
			return f
		}
		return val.String()
	case map[string]any:
		for k, v2 := range val {
			val[k] = convertJSONNumbers(v2)
		}
		return val
	case []any:
		for i, v2 := range val {
			val[i] = convertJSONNumbers(v2)
		}
		return val
	default:
		return v
	}
}

