// ============================================================
// Merge: SamlAssertion
// ============================================================
// MergeSamlAssertion fills zero-valued fields in dst from src.
func MergeSamlAssertion(dst, src *SamlAssertion) {
	if dst.ResponseId == "" {
		dst.ResponseId = src.ResponseId
	}
	if dst.InResponseTo == "" {
		dst.InResponseTo = src.InResponseTo
	}
	if dst.StatusCode == "" {
		dst.StatusCode = src.StatusCode
	}
	if dst.StatusMessage == "" {
		dst.StatusMessage = src.StatusMessage
	}
	if dst.Id == "" {
		dst.Id = src.Id
	}
	if dst.IssueInstant == "" {
		dst.IssueInstant = src.IssueInstant
	}
	if dst.Issuer == "" {
		dst.Issuer = src.Issuer
	}
	if dst.SubjectNameId == "" {
		dst.SubjectNameId = src.SubjectNameId
	}
	if dst.NameIdFormat == "" {
		dst.NameIdFormat = src.NameIdFormat
	}
	if dst.SubjectRecipient == "" {
		dst.SubjectRecipient = src.SubjectRecipient
	}
	if dst.SubjectNotOnOrAfter == "" {
		dst.SubjectNotOnOrAfter = src.SubjectNotOnOrAfter
	}
	if dst.NotBefore == "" {
		dst.NotBefore = src.NotBefore
	}
	if dst.NotOnOrAfter == "" {
		dst.NotOnOrAfter = src.NotOnOrAfter
	}
	if len(dst.Audiences) == 0 {
		dst.Audiences = src.Audiences
	}
	if dst.AuthnInstant == "" {
		dst.AuthnInstant = src.AuthnInstant
	}
	if dst.AuthnContext == "" {
		dst.AuthnContext = src.AuthnContext
	}
	if dst.SessionIndex == "" {
		dst.SessionIndex = src.SessionIndex
	}
	if len(dst.Attributes) == 0 {
		dst.Attributes = src.Attributes
	}
	if dst.Xml == "" {
		dst.Xml = src.Xml
	}
}

// ============================================================
// Merge: SamlEndpoint
// ============================================================
// MergeSamlEndpoint fills zero-valued fields in dst from src.
func MergeSamlEndpoint(dst, src *SamlEndpoint) {
	if dst.Binding == "" {
		dst.Binding = src.Binding
	}
	if dst.Location == "" {
		dst.Location = src.Location
	}
	if dst.Index == 0 {
		dst.Index = src.Index
	}
}

// ============================================================
// Merge: SamlEntityDescriptor
// ============================================================
// MergeSamlEntityDescriptor fills zero-valued fields in dst from src.
func MergeSamlEntityDescriptor(dst, src *SamlEntityDescriptor) {
	if dst.EntityId == "" {
		dst.EntityId = src.EntityId
	}
	if dst.SigningCert == nil {
		dst.SigningCert = src.SigningCert
	}
	if len(dst.SsoServices) == 0 {
		dst.SsoServices = src.SsoServices
	}
	if len(dst.AcsUrls) == 0 {
		dst.AcsUrls = src.AcsUrls
	}
	if len(dst.SloServices) == 0 {
		dst.SloServices = src.SloServices
	}
	if !dst.WantAuthnRequestsSigned {
		dst.WantAuthnRequestsSigned = src.WantAuthnRequestsSigned
	}
	if !dst.AuthnRequestsSigned {
		dst.AuthnRequestsSigned = src.AuthnRequestsSigned
	}
}
